
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_gx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_gx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.129842771020283e+00, -5.026080225352802e+00, -4.880643745190889e+00, -4.679091254295842e+00, -4.404258907931812e+00, -4.038044251849566e+00, -3.565663489617652e+00, -2.983092625494602e+00, -2.305500169700429e+00, -1.559904815148044e+00, -8.386916117026836e-01, -6.332897323154805e-01, -6.497859084951371e-01, -5.495658678206222e-01, -3.744162442216373e-01, -2.024212213429630e-01, -8.110864312510122e-02, -2.484193850309117e-02, -5.139679149197438e-03, -5.746237417534395e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


